#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Create a string stream to hold the HTML output
    std::stringstream htmlStream;

    // Write the markdown text to the string stream
    htmlStream << markdown;

    // Return the HTML text as a string
    return htmlStream.str();
}

int main() {
    // Example usage
    std::string markdown = "# Markdown Text\n\nThis is a markdown text";
    std::string html = markdownToHtml(markdown);
    std::cout << "Markdown Text: " << markdown << std::endl;
    std::cout << "HTML Text: " << html << std::endl;
    return 0;
}
```

